def page(items: list, number: int, size: int) -> list:
    start = (number - 1) * size
    return items[start:start + size]

from catalog.pager import page


def test_first_page_starts_at_first_item():
    assert page([1, 2, 3, 4, 5], 1, 2) == [1, 2]


def test_second_page_follows_first_page():
    assert page([1, 2, 3, 4, 5], 2, 2) == [3, 4]


def test_last_page_can_be_partial():
    assert page([1, 2, 3, 4, 5], 3, 2) == [5]


def test_page_past_end_is_empty():
    assert page([1, 2, 3, 4, 5], 4, 2) == []


def test_empty_items_returns_empty_page():
    assert page([], 1, 2) == []
